// One-bit down-counter with load, triggered on the positive edge of the
// clock -> roughly a timer that goes to 0 at the end of the count, with an
// optional load-to-count shortcut (goes to the loaded value instantly).
module TopModule(input clk, input load, input [9:0] data, output tc);
  reg [9:0] count;
  reg [9:0] next_count;
  wire go;
  reg tc2;
  always @(*) begin
    next_count = (go ? count - 1 : count);
    tc2 = (count == 1);
  end
  always @(posedge clk) begin
    count <= next_count;
    if (load) count <= data;
  end
  assign go = (count != 0);
  assign tc = tc2;
endmodule

